using System.Numerics;
using Hexa.NET.ImGui;

namespace Zenith.NET.Extensions.ImGui;

internal unsafe class ImGuiRenderer : DisposableObject
{
    public const string Source = @"
struct VSInput
{
    float2 Position : POSITION0;
    
    float2 UV : TEXCOORD0;
    
    float4 Color : COLOR0;
};

struct VSOutput
{
    float4 Position : SV_POSITION;
    
    float2 UV : TEXCOORD0;
    
    float4 Color : COLOR0;
};

struct Constants
{
    float4x4 Projection;
};

uniform Constants constants;
uniform Texture2D texture;
uniform SamplerState sampler;

float3 SrgbToLinear(float3 srgb)
{
    return srgb * (srgb * (srgb * 0.305306011 + 0.682171111) + 0.012522878);
}

VSOutput VSMain(VSInput input)
{
    VSOutput output;
    
    output.Position = mul(float4(input.Position, 0.0, 1.0), constants.Projection);
    output.UV = input.UV;
    output.Color = input.Color;
    
#if 0
    output.Color.rgb = SrgbToLinear(output.Color.rgb);
#endif
    
    return output;
}

float4 PSMain(VSOutput input) : SV_TARGET
{
    return input.Color * texture.Sample(sampler, input.UV);
}
";

    private readonly string[] Dxil =
    [
        // Vertex Shader - Legacy
        "",

        // Vertex Shader - Linear
        "",

        // Pixel Shader
        ""
    ];

    private readonly ResourceLayoutDesc DxilDesc = new()
    {
        Bindings =
        [
            new ResourceBinding() { Type = ResourceType.ConstantBuffer, Index = 0, Count = 1, StageFlags = ShaderStageFlags.Vertex },
            new ResourceBinding() { Type = ResourceType.Texture, Index = 0, Count = 1, StageFlags = ShaderStageFlags.Pixel },
            new ResourceBinding() { Type = ResourceType.Sampler, Index = 0, Count = 1, StageFlags = ShaderStageFlags.Pixel }
        ]
    };

    private readonly string[] Spirv =
    [
        // Vertex Shader - Legacy
        "",

        // Vertex Shader - Linear
        "",

        // Pixel Shader
        ""
    ];

    private readonly ResourceLayoutDesc SpirvDesc = new()
    {
        Bindings =
        [
            new ResourceBinding() { Type = ResourceType.ConstantBuffer, Index = 0, Count = 1, StageFlags = ShaderStageFlags.Vertex },
            new ResourceBinding() { Type = ResourceType.Texture, Index = 1, Count = 1, StageFlags = ShaderStageFlags.Pixel },
            new ResourceBinding() { Type = ResourceType.Sampler, Index = 2, Count = 1, StageFlags = ShaderStageFlags.Pixel }
        ]
    };

    private struct Constants
    {
        public Matrix4x4 Projection;
    }

    private readonly Buffer constants;
    private readonly Sampler sampler;
    private readonly ResourceLayout resourceLayout;
    private readonly GraphicsPipeline graphicsPipeline;
    private readonly Dictionary<Texture, ImTextureID> textures = [];
    private readonly Dictionary<TextureView, ImTextureID> textureViews = [];
    private readonly Dictionary<ImTextureID, Texture> textureBindings = [];
    private readonly Dictionary<ImTextureID, ResourceSet> resourceSetBindings = [];

    public ImGuiRenderer(GraphicsContext context, Output output, ImGuiColorSpace colorSpace)
    {
        byte[] vertexShaderBytes = [];
        byte[] pixelShaderBytes = [];
        ResourceLayoutDesc resourceLayoutDesc = default;
        switch (context.Backend)
        {
            case Backend.DirectX12:
                vertexShaderBytes = Convert.FromHexString(colorSpace is ImGuiColorSpace.Legacy ? Dxil[0] : Dxil[1]);
                pixelShaderBytes = Convert.FromHexString(Dxil[2]);
                resourceLayoutDesc = DxilDesc;
                break;

            case Backend.Vulkan:
                vertexShaderBytes = Convert.FromHexString(colorSpace is ImGuiColorSpace.Legacy ? Spirv[0] : Spirv[1]);
                pixelShaderBytes = Convert.FromHexString(Spirv[2]);
                resourceLayoutDesc = SpirvDesc;
                break;
        }

        using Shader vertex = context.CreateShader(new()
        {
            ShaderBytes = vertexShaderBytes,
            EntryPoint = "VSMain",
            Stage = ShaderStageFlags.Vertex
        });

        using Shader pixel = context.CreateShader(new()
        {
            ShaderBytes = pixelShaderBytes,
            EntryPoint = "PSMain",
            Stage = ShaderStageFlags.Pixel
        });

        constants = context.CreateBuffer(new()
        {
            SizeInBytes = (uint)sizeof(Constants),
            StrideInBytes = (uint)sizeof(Constants),
            Flags = BufferUsageFlags.Constant | BufferUsageFlags.Dynamic
        });

        sampler = context.CreateSampler(new()
        {
            U = AddressMode.Clamp,
            V = AddressMode.Clamp,
            W = AddressMode.Clamp,
            Filter = Filter.MinPointMagPointMipPoint
        });

        resourceLayout = context.CreateResourceLayout(resourceLayoutDesc);

        InputLayout inputLayout = new();
        inputLayout.Add(new() { Format = ElementFormat.Float2, Semantic = ElementSemantic.Position });
        inputLayout.Add(new() { Format = ElementFormat.Float2, Semantic = ElementSemantic.TexCoord });
        inputLayout.Add(new() { Format = ElementFormat.Float4, Semantic = ElementSemantic.Color });

        graphicsPipeline = context.CreateGraphicsPipeline(new()
        {
            RenderStates = new()
            {
                RasterizerState = RasterizerStates.Default,
                DepthStencilState = DepthStencilStates.None,
                BlendState = BlendStates.AlphaBlend
            },
            Vertex = vertex,
            Pixel = pixel,
            ResourceLayouts = [resourceLayout],
            InputLayouts = [inputLayout],
            PrimitiveTopology = PrimitiveTopology.TriangleList,
            Output = output
        });

        Context = context;
    }

    public GraphicsContext Context { get; }

    public ImTextureRef Binding(Texture texture)
    {
        if (!textures.TryGetValue(texture, out ImTextureID textureID))
        {
            ulong id = 0;
            while (textures.Values.Any(item => item == id))
            {
                id++;
            }

            resourceSetBindings[textures[texture] = textureID = id] = Context.CreateResourceSet(new()
            {
                Layout = resourceLayout,
                Resources = [constants, texture, sampler]
            });
        }

        return new(null, textureID);
    }

    public ImTextureRef Binding(TextureView textureView)
    {
        if (!textureViews.TryGetValue(textureView, out ImTextureID textureID))
        {
            ulong id = 0;
            while (textureViews.Values.Any(item => item == id))
            {
                id++;
            }

            resourceSetBindings[textureViews[textureView] = textureID = id] = Context.CreateResourceSet(new()
            {
                Layout = resourceLayout,
                Resources = [constants, textureView, sampler]
            });
        }

        return new(null, textureID);
    }

    public void Render(CommandBuffer commandBuffer, ImDrawDataPtr drawData)
    {
        for (int i = 0; i < drawData.Textures.Size; i++)
        {
            ImTextureDataPtr textureData = drawData.Textures[i];

            switch (textureData.Status)
            {
                case ImTextureStatus.WantCreate:
                    {
                        Texture texture = Context.CreateTexture(new()
                        {
                            Type = TextureType.Texture2D,
                            Format = textureData.Format is ImTextureFormat.Rgba32 ? PixelFormat.R8G8B8A8UNorm : PixelFormat.R8UNorm,
                            Width = (uint)textureData.Width,
                            Height = (uint)textureData.Height,
                            Depth = 1,
                            MipLevels = 1,
                            ArrayLayers = 1,
                            SampleCount = SampleCount.Count1,
                            Flags = TextureUsageFlags.ShaderResource
                        });
                    }
                    break;

                case ImTextureStatus.WantUpdates:
                    break;

                case ImTextureStatus.WantDestroy:
                    break;
            }
        }
    }

    protected override void Destroy()
    {
        foreach (ResourceSet binding in resourceSetBindings.Values)
        {
            binding.Dispose();
        }

        foreach (Texture binding in textureBindings.Values)
        {
            binding.Dispose();
        }

        resourceSetBindings.Clear();
        textureBindings.Clear();
        textureViews.Clear();
        textures.Clear();
        graphicsPipeline.Dispose();
        resourceLayout.Dispose();
        sampler.Dispose();
        constants.Dispose();
    }
}
